template:
use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    for i in 1..=3 {
        let tx = ⟦slot1⟧;
        thread::spawn(move || {
            tx.send(i).unwrap();
        });
    }
    ⟦slot2⟧;
    let mut res: Vec<i32> =
        rx.into_iter().collect();
    res.sort();
    assert_eq!(res, vec![1, 2, 3]);
}
